// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;

    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        Reentrant r = new Reentrant(c);
        vm.deal(address(r), amount);
        r.deposit(amount);
        assertEq(c.balances(address(r)), amount);
        r.attack();
        // Invariant: at the moment of the reentrant callback, the caller's
        // balance is still the full deposited amount (P satisfies for all
        // inputs; M zeroes it before the call and reads 0).
        assertTrue(r.observedDuringCallback() == amount);
    }
}

contract Reentrant {
    keepMyEther c;
    uint256 public observedDuringCallback;

    constructor(keepMyEther _c) { c = _c; }

    function deposit(uint256 amt) external payable {
        (bool ok, ) = address(c).call{value: amt}("");
        require(ok);
    }

    function attack() external {
        c.withdraw();
    }

    receive() external payable {
        observedDuringCallback = c.balances(address(this));
    }
}
